import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { getProducts, getOrders, getAlerts, getPurchaseOrders } from "./src/queries" with { type: "ref" };
import { fulfillOrder } from "./src/actions" with { type: "ref" };
import { seedData } from "./src/seeds" with { type: "ref" };

export default app({
  name: "app",
  title: "Warehouse Inventory Tracker",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
  },
  db: {
    seeds: [seedData],
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),
    query(getProducts, { entities: ["Product", "Supplier"] }),
    query(getOrders, { entities: ["Order", "OrderItem", "Product"] }),
    query(getAlerts, { entities: ["Alert"] }),
    query(getPurchaseOrders, { entities: ["PurchaseOrder", "Supplier", "Product"] }),
    action(fulfillOrder, { entities: ["Order", "OrderItem", "Product", "PurchaseOrder", "Alert", "Supplier"] }),
  ],
});

