import type { PrismaClient } from "@prisma/client";

export const seedData = async (prisma: PrismaClient) => {
  // Clear any existing records to avoid conflicts
  await prisma.orderItem.deleteMany({});
  await prisma.order.deleteMany({});
  await prisma.purchaseOrder.deleteMany({});
  await prisma.alert.deleteMany({});
  await prisma.product.deleteMany({});
  await prisma.supplier.deleteMany({});
  await prisma.user.deleteMany({});

  // 1. Create User
  await prisma.user.create({
    data: {
      username: "warehouse_manager",
      password: "password123",
    },
  });

  // 2. Create Suppliers
  await prisma.supplier.create({
    data: {
      id: 1,
      name: "Global Tech Distributors",
      email: "supply@globaltech.com",
    },
  });

  await prisma.supplier.create({
    data: {
      id: 2,
      name: "Apex Logistics",
      email: "orders@apexlogistics.com",
    },
  });

  // 3. Create Products
  await prisma.product.create({
    data: {
      id: 1,
      sku: "PROD-001",
      name: "Wireless Mouse",
      stock: 15,
      lowStockThreshold: 10,
      reorderQuantity: 50,
      supplierId: 1,
    },
  });

  await prisma.product.create({
    data: {
      id: 2,
      sku: "PROD-002",
      name: "Mechanical Keyboard",
      stock: 8,
      lowStockThreshold: 5,
      reorderQuantity: 20,
      supplierId: 2,
    },
  });

  // 4. Create Customer Orders
  await prisma.order.create({
    data: {
      id: 1,
      customerName: "TechCorp Solutions",
      status: "PENDING",
      orderItems: {
        create: [
          { productId: 1, quantity: 8 },
          { productId: 2, quantity: 2 },
        ],
      },
    },
  });

  await prisma.order.create({
    data: {
      id: 2,
      customerName: "RetailHub",
      status: "PENDING",
      orderItems: {
        create: [
          { productId: 1, quantity: 10 },
          { productId: 2, quantity: 2 },
        ],
      },
    },
  });
};

import type { GetProducts, GetOrders, GetAlerts, GetPurchaseOrders } from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const getProducts: GetProducts<void, any[]> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  return context.entities.Product.findMany({
    include: {
      supplier: true,
    },
    orderBy: {
      id: "asc",
    },
  });
};

export const getOrders: GetOrders<void, any[]> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  return context.entities.Order.findMany({
    include: {
      orderItems: {
        include: {
          product: true,
        },
      },
    },
    orderBy: {
      id: "asc",
    },
  });
};

export const getAlerts: GetAlerts<void, any[]> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  return context.entities.Alert.findMany({
    orderBy: {
      createdAt: "desc",
    },
  });
};

export const getPurchaseOrders: GetPurchaseOrders<void, any[]> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  return context.entities.PurchaseOrder.findMany({
    include: {
      supplier: true,
      product: true,
    },
    orderBy: {
      createdAt: "desc",
    },
  });
};

import type { FulfillOrder } from "wasp/server/operations";
import { HttpError } from "wasp/server";
import { prisma } from "wasp/server";

export const fulfillOrder: FulfillOrder<{ orderId: number }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const { orderId } = args;

  return await prisma.$transaction(async (tx) => {
    // 1. Fetch the order with its items
    const order = await tx.order.findUnique({
      where: { id: orderId },
      include: {
        orderItems: {
          include: {
            product: true,
          },
        },
      },
    });

    if (!order) {
      throw new HttpError(404, `Order with ID ${orderId} not found.`);
    }

    if (order.status === "FULFILLED") {
      throw new HttpError(400, `Order ${orderId} is already fulfilled.`);
    }

    // 2. Check stock for each item in the order
    for (const item of order.orderItems) {
      const product = await tx.product.findUnique({
        where: { id: item.productId },
      });

      if (!product) {
        throw new HttpError(404, `Product ${item.product.name} not found.`);
      }

      if (product.stock < item.quantity) {
        throw new HttpError(
          400,
          `Insufficient stock for ${product.name} (SKU: ${product.sku}). Requested: ${item.quantity}, Available: ${product.stock}.`
        );
      }
    }

    // 3. Decrement stock, check lowStockThreshold, trigger alerts/PO
    for (const item of order.orderItems) {
      const product = await tx.product.findUnique({
        where: { id: item.productId },
      });

      if (!product) {
        throw new HttpError(404, `Product ${item.product.name} not found.`);
      }

      const newStock = product.stock - item.quantity;

      // Update product stock
      await tx.product.update({
        where: { id: product.id },
        data: { stock: newStock },
      });

      // 4. Check low stock threshold
      if (newStock < product.lowStockThreshold) {
        // Create an Alert record
        const alertMessage = `Low stock alert for ${product.name} (SKU: ${product.sku}). Current stock: ${newStock}.`;
        await tx.alert.create({
          data: {
            productId: product.id,
            message: alertMessage,
          },
        });

        // Check if there is already an existing PurchaseOrder for this product with status "SENT"
        const existingPO = await tx.purchaseOrder.findFirst({
          where: {
            productId: product.id,
            status: "SENT",
          },
        });

        if (!existingPO) {
          await tx.purchaseOrder.create({
            data: {
              supplierId: product.supplierId,
              productId: product.id,
              quantity: product.reorderQuantity,
              status: "SENT",
            },
          });
        }
      }
    }

    // 5. Set order status to "FULFILLED"
    const updatedOrder = await tx.order.update({
      where: { id: orderId },
      data: { status: "FULFILLED" },
    });

    return updatedOrder;
  });
};

import { LoginForm } from "wasp/client/auth";

export function LoginPage() {
  return (
    <div style={{ display: "flex", justifyContent: "center", alignItems: "center", height: "100vh", flexDirection: "column", backgroundColor: "#f3f4f6" }}>
      <div style={{ padding: "2rem", backgroundColor: "white", borderRadius: "8px", boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)", minWidth: "320px" }}>
        <h2 style={{ textAlign: "center", marginBottom: "1.5rem", color: "#1f2937" }}>Warehouse Manager Login</h2>
        <LoginForm />
        <p style={{ marginTop: "1rem", textAlign: "center", fontSize: "0.875rem", color: "#4b5563" }}>
          Don't have an account? <a href="/signup" style={{ color: "#3b82f6", textDecoration: "none", fontWeight: "bold" }}>Sign up</a>
        </p>
      </div>
    </div>
  );
}

import { SignupForm } from "wasp/client/auth";

export function SignupPage() {
  return (
    <div style={{ display: "flex", justifyContent: "center", alignItems: "center", height: "100vh", flexDirection: "column", backgroundColor: "#f3f4f6" }}>
      <div style={{ padding: "2rem", backgroundColor: "white", borderRadius: "8px", boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)", minWidth: "320px" }}>
        <h2 style={{ textAlign: "center", marginBottom: "1.5rem", color: "#1f2937" }}>Warehouse Manager Signup</h2>
        <SignupForm />
        <p style={{ marginTop: "1rem", textAlign: "center", fontSize: "0.875rem", color: "#4b5563" }}>
          Already have an account? <a href="/login" style={{ color: "#3b82f6", textDecoration: "none", fontWeight: "bold" }}>Login</a>
        </p>
      </div>
    </div>
  );
}

